package dominoes

// Domino represents a domino stone with two halves of dots.
type Domino [2]int

// MakeChain attempts to arrange the given dominoes into a closed chain,
// where adjacent halves match and the outer halves of the ends match too.
// Dominoes may be rotated as needed. Returns ok=false if no such chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}
	used := make([]bool, len(input))
	chain := make([]Domino, 0, len(input))
	if arrange(input, used, &chain, input[0][0]) {
		return chain, true
	}
	return nil, false
}

// arrange tries to place all unused dominoes after `start`, ending back at `start`.
func arrange(input []Domino, used []bool, chain *[]Domino, start int) bool {
	remaining := 0
	for _, u := range used {
		if !u {
			remaining++
		}
	}
	if remaining == 0 {
		return true
	}
	for i, d := range input {
		if used[i] {
			continue
		}
		a, b := d[0], d[1]
		// Try orientation (a, b) if a matches current open end.
		if a == start {
			used[i] = true
			*chain = append(*chain, Domino{a, b})
			if arrange(input, used, chain, b) {
				return true
			}
			*chain = (*chain)[:len(*chain)-1]
			used[i] = false
		}
		// Try rotated orientation (b, a) if b matches current open end.
		if b == start && a != b {
			used[i] = true
			*chain = append(*chain, Domino{b, a})
			if arrange(input, used, chain, a) {
				return true
			}
			*chain = (*chain)[:len(*chain)-1]
			used[i] = false
		}
	}
	return false
}

