package dominoes

import "fmt"

// Domino represents a domino stone with two halves of dots.
type Domino [2]int

// MakeChain attempts to arrange all the given dominoes into a closed chain,
// where adjacent halves match and the outer halves of the two ends match too.
// Dominoes may be rotated as needed; each input domino must be used exactly once.
// An empty input is considered legal. Returns ok=false if no chain exists.
//
// The problem is equivalent to finding an Eulerian circuit in the multigraph
// whose vertices are pip values and whose edges are the dominoes: such a
// circuit exists iff every vertex has even degree and all edges lie in a
// single connected component. The circuit is found with Hierholzer's algorithm.
func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)
	if n == 0 {
		return []Domino{}, true
	}

	// Parity check: every vertex must have even degree.
	deg := map[int]int{}
	for _, d := range input {
		deg[d[0]]++
		deg[d[1]]++
	}
	for _, v := range deg {
		if v%2 != 0 {
			return nil, false
		}
	}

	// Connectivity check (union-find) over vertices that appear on a domino.
	parent := make(map[int]int, len(deg))
	for x := range deg {
		parent[x] = x
	}
	var find func(int) int
	find = func(x int) int {
		if parent[x] != x {
			parent[x] = find(parent[x])
		}
		return parent[x]
	}
	for _, d := range input {
		ra, rb := find(d[0]), find(d[1])
		if ra != rb {
			parent[ra] = rb
		}
	}
	root := -1
	first := true
	for x := range deg {
		r := find(x)
		if first {
			root, first = r, false
		} else if r != root {
			return nil, false
		}
	}

	// Build adjacency lists of edge indices (a double is one self-loop entry).
	adj := make(map[int][]int, len(deg))
	for i, d := range input {
		adj[d[0]] = append(adj[d[0]], i)
		if d[1] != d[0] {
			adj[d[1]] = append(adj[d[1]], i)
		}
	}

	// Hierholzer's algorithm, iteratively, recording the domino (half1, half2)
	// used to reach each stack entry.
	type item struct {
		v int
		d *Domino
	}
	used := make([]bool, n)
	ptr := make(map[int]int, len(adj))
	stack := []item{{v: input[0][0], d: nil}}
	var out []item
	for len(stack) > 0 {
		top := &stack[len(stack)-1]
		list := adj[top.v]
		p := ptr[top.v]
		for p < len(list) && used[list[p]] {
			p++
		}
		ptr[top.v] = p
		if p < len(list) {
			e := list[p]
			ptr[top.v] = p + 1
			if used[e] {
				return nil, fmt.Errorf("internal: edge %d used twice", e)
			}
			used[e] = true
			a, b := input[e][0], input[e][1]
			w := b
			if a != top.v {
				w = a
			}
			d := Domino{top.v, w}
			stack = append(stack, item{v: w, d: &d})
		} else {
			out = append(out, *top)
			stack = stack[:len(stack)-1]
		}
	}

	// Defensive: a correct Eulerian circuit must consume every edge.
	for _, u := range used {
		if !u {
			return nil, false
		}
	}

	// Popped entries are the cycle in reverse order; reverse them to get
	// a chain whose last half matches its first half (it is a cycle).
	chain := make([]Domino, 0, n)
	for i := len(out) - 1; i >= 0; i-- {
		if out[i].d != nil {
			chain = append(chain, *out[i].d)
		}
	}
	return chain, true
}

