	np := func(d Domino) Domino {
		if d[0] > d[1] {
			return Domino{d[1], d[0]}
		}
		return d
	}
	want := map[Domino]int{}
	for _, d := range input {
		want[np(d)]++
	}
	got := map[Domino]int{}
	for _, d := range c {
		got[np(d)]++
	}
	for k, v := range want {
		if got[k] != v {
			t.Fatalf("multiset mismatch for %v: want %d got %d", k, v, got[k])
		}
	}
}

